ALTER TABLE public.organisations ADD COLUMN idle_timeout_minutes integer NOT NULL DEFAULT 60 CHECK(idle_timeout_minutes BETWEEN 15 AND 480), ADD COLUMN max_session_hours integer NOT NULL DEFAULT 12 CHECK(max_session_hours BETWEEN 1 AND 168);
CREATE FUNCTION public.session_settings_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.idle_timeout_minutes,NEW.max_session_hours) IS DISTINCT FROM (OLD.idle_timeout_minutes,OLD.max_session_hours) AND NOT public.has_org_role(OLD.id,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins may change session security'; END IF;RETURN NEW;END $$;
CREATE TRIGGER session_settings_guard BEFORE UPDATE ON public.organisations FOR EACH ROW EXECUTE FUNCTION public.session_settings_guard();
CREATE TABLE public.session_security_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organisations(id),actor uuid NOT NULL,target_user uuid NOT NULL,session_id uuid,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.session_security_events TO authenticated;GRANT ALL ON public.session_security_events TO service_role;
ALTER TABLE public.session_security_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY session_security_events_read ON public.session_security_events FOR SELECT TO authenticated USING(public.has_org_role(org_id,ARRAY['org_admin']::public.app_role[]));
CREATE TRIGGER session_security_events_audit AFTER INSERT ON public.session_security_events FOR EACH ROW EXECUTE FUNCTION public.audit_capture();
CREATE FUNCTION public.session_security_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Session security history is immutable'; END $$;
CREATE TRIGGER session_security_events_immutable BEFORE UPDATE OR DELETE ON public.session_security_events FOR EACH ROW EXECUTE FUNCTION public.session_security_events_immutable();
CREATE FUNCTION public.mask_session_ip(_ip inet) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN _ip IS NULL THEN NULL WHEN family(_ip)=4 THEN host(network(set_masklen(_ip,24)))||'/24' ELSE host(network(set_masklen(_ip,48)))||'/48' END $$;
CREATE FUNCTION public.my_sessions() RETURNS TABLE(id uuid,created_at timestamptz,last_active timestamptz,user_agent text,ip text,aal text,is_current boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;RETURN QUERY SELECT s.id,s.created_at,coalesce((to_jsonb(s)->>'refreshed_at')::timestamp AT TIME ZONE 'UTC',s.updated_at,s.created_at),s.user_agent,public.mask_session_ip(s.ip),s.aal::text,s.id=nullif(auth.jwt()->>'session_id','')::uuid FROM auth.sessions s WHERE s.user_id=auth.uid() ORDER BY s.created_at DESC;END $$;
CREATE FUNCTION public.revoke_my_session(_session uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _session=nullif(auth.jwt()->>'session_id','')::uuid THEN RAISE EXCEPTION 'Use sign out for this device'; END IF;IF NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=_session AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Session access denied';END IF;DELETE FROM auth.sessions WHERE id=_session AND user_id=auth.uid();FOR o IN SELECT org_id FROM public.org_members WHERE user_id=auth.uid() AND active LOOP INSERT INTO public.session_security_events(org_id,actor,target_user,session_id,kind) VALUES(o,auth.uid(),auth.uid(),_session,'session_revoked');END LOOP;END $$;
CREATE FUNCTION public.revoke_member_sessions(_org uuid,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) OR NOT EXISTS(SELECT 1 FROM public.org_members WHERE org_id=_org AND user_id=_user) THEN RAISE EXCEPTION 'Member session access denied'; END IF;DELETE FROM auth.sessions WHERE user_id=_user;INSERT INTO public.session_security_events(org_id,actor,target_user,kind) VALUES(_org,auth.uid(),_user,'member_sessions_revoked');END $$;
CREATE FUNCTION public.member_sessions_deactivated() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' OR (OLD.active AND NOT NEW.active) THEN DELETE FROM auth.sessions WHERE user_id=OLD.user_id;INSERT INTO public.session_security_events(org_id,actor,target_user,kind) VALUES(OLD.org_id,coalesce(auth.uid(),OLD.user_id),OLD.user_id,'member_deactivated');END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER member_sessions_deactivated AFTER UPDATE OR DELETE ON public.org_members FOR EACH ROW EXECUTE FUNCTION public.member_sessions_deactivated();
CREATE FUNCTION public.session_expiry_job(_at timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer;BEGIN DELETE FROM auth.sessions s USING (SELECT m.user_id,min(o.max_session_hours) hours FROM public.org_members m JOIN public.organisations o ON o.id=m.org_id WHERE m.active GROUP BY m.user_id) limits WHERE s.user_id=limits.user_id AND s.created_at<_at-make_interval(hours=>limits.hours);GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END $$;
CREATE FUNCTION public.org_session_summary(_org uuid) RETURNS TABLE(user_id uuid,session_count bigint,last_active timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_org_role(_org,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins may view session counts';END IF;RETURN QUERY SELECT m.user_id,count(s.id),max(coalesce((to_jsonb(s)->>'refreshed_at')::timestamp AT TIME ZONE 'UTC',s.updated_at,s.created_at)) FROM public.org_members m LEFT JOIN auth.sessions s ON s.user_id=m.user_id WHERE m.org_id=_org AND m.active GROUP BY m.user_id;END $$;
CREATE FUNCTION public.my_session_limits() RETURNS TABLE(idle_timeout_minutes integer,max_session_hours integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required';END IF;RETURN QUERY SELECT coalesce(min(o.idle_timeout_minutes),60),coalesce(min(o.max_session_hours),12) FROM public.org_members m JOIN public.organisations o ON o.id=m.org_id WHERE m.user_id=auth.uid() AND m.active;END $$;
REVOKE ALL ON FUNCTION public.my_sessions(),public.revoke_my_session(uuid),public.revoke_member_sessions(uuid,uuid),public.org_session_summary(uuid),public.my_session_limits() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_sessions(),public.revoke_my_session(uuid),public.revoke_member_sessions(uuid,uuid),public.org_session_summary(uuid),public.my_session_limits() TO authenticated;
REVOKE ALL ON FUNCTION public.session_expiry_job(timestamptz) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.session_expiry_job(timestamptz) TO service_role;